codeExamples.code:
-- Create the hierarchy
CREATE CATALOG IF NOT EXISTS prod;
CREATE SCHEMA IF NOT EXISTS prod.sales;
CREATE TABLE prod.sales.orders (
  order_id BIGINT,
  customer_id BIGINT,
  amount DECIMAL(10,2),
  order_date DATE
) USING DELTA;

-- Set the active catalog/schema so you can use short names
USE CATALOG prod;
USE SCHEMA sales;
SELECT * FROM orders;            -- resolves to prod.sales.orders

-- Or always fully qualify
SELECT * FROM prod.sales.orders;

-- Identity-based, ANSI SQL governance with inheritance
GRANT USE CATALOG ON CATALOG prod TO `data_analysts`;
GRANT USE SCHEMA  ON SCHEMA  prod.sales TO `data_analysts`;
GRANT SELECT ON TABLE prod.sales.orders TO `data_analysts`;

-- Govern external (customer-managed) storage
CREATE STORAGE CREDENTIAL finance_cred
  WITH AWS_IAM_ROLE 'arn:aws:iam::123456789012:role/uc-finance';

CREATE EXTERNAL LOCATION finance_loc
  URL 's3://company-lake/finance'
  WITH (STORAGE CREDENTIAL finance_cred);

GRANT READ FILES ON EXTERNAL LOCATION finance_loc TO `finance_team`;

-- Managed table: Unity Catalog owns the storage lifecycle (DROP deletes data)
CREATE TABLE prod.sales.orders_managed (id BIGINT) USING DELTA;

-- External table: data lives at a customer-managed path (DROP keeps data)
CREATE TABLE prod.sales.orders_external (id BIGINT)
USING DELTA
LOCATION 's3://company-lake/finance/orders_external';

-- Access legacy two-level objects through the built-in hive_metastore catalog
SELECT * FROM hive_metastore.default.legacy_orders;

-- Migrate a legacy table into Unity Catalog
CREATE TABLE prod.sales.orders AS
SELECT * FROM hive_metastore.default.legacy_orders;
